static bool Decode(const std::filesystem::path&p,Image&i){ComPtr<IWICImagingFactory>f;ComPtr<IWICBitmapDecoder>d;ComPtr<IWICBitmapFrameDecode>r;ComPtr<IWICFormatConverter>c;if(FAILED(CoCreateInstance(CLSID_WICImagingFactory,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&f)))||FAILED(f->CreateDecoderFromFilename(p.c_str(),nullptr,GENERIC_READ,WICDecodeMetadataCacheOnLoad,&d))||FAILED(d->GetFrame(0,&r))||FAILED(r->GetSize(&i.width,&i.height))||FAILED(f->CreateFormatConverter(&c))||FAILED(c->Initialize(r.Get(),GUID_WICPixelFormat32bppRGBA,WICBitmapDitherTypeNone,nullptr,0,WICBitmapPaletteTypeCustom)))return false;i.rgba.resize(size_t(i.width)*i.height*4);return SUCCEEDED(c->CopyPixels(nullptr,i.width*4,UINT(i.rgba.size()),i.rgba.data()));}
static Metrics Measure(const Image&i,const ObjectIdCapture3D&o,RenderObjectIdentity3D id){Metrics r{};std::vector<double>v;for(size_t n=0;n<o.pixels.size();++n){const auto*x=o.Resolve(o.pixels[n]);if(!x||*x!=id)continue;const size_t p=n*4;const double l=.2126*i.rgba[p]+.7152*i.rgba[p+1]+.0722*i.rgba[p+2];v.push_back(l);r.black+=l<10;r.top+=n/i.width<i.height/3;r.bottom+=n/i.width>=i.height*2/3;}r.count=v.size();if(v.empty())return r;std::ranges::sort(v);r.mean=std::accumulate(v.begin(),v.end(),0.)/v.size();r.p10=v[(v.size()-1)/10];r.black/=v.size();return r;}
static Metrics MeasureRect(const Image&i,unsigned left,unsigned top,unsigned right,unsigned bottom){Metrics r{};std::vector<double>v;for(unsigned y=top;y<(std::min)(bottom,i.height);++y)for(unsigned x=left;x<(std::min)(right,i.width);++x){const size_t p=(size_t(y)*i.width+x)*4;const double l=.2126*i.rgba[p]+.7152*i.rgba[p+1]+.0722*i.rgba[p+2];v.push_back(l);r.black+=l<10;}r.count=v.size();if(v.empty())return r;std::ranges::sort(v);r.mean=std::accumulate(v.begin(),v.end(),0.)/v.size();r.p10=v[(v.size()-1)/10];r.black/=v.size();return r;}
static uint64_t P95(std::vector<uint64_t>v){std::ranges::sort(v);return v[(v.size()*95+99)/100-1];}
static uint64_t P50(std::vector<uint64_t>v){std::ranges::sort(v);return v[v.size()/2];}
static uint64_t Maximum(const std::vector<uint64_t>&v){return v.empty()?0:*std::ranges::max_element(v);}
static void PrintSamples(const char*label,const std::vector<uint64_t>&samples,uint64_t timingBefore,uint64_t timingAfter,uint64_t serialBefore,uint64_t serialAfter){std::cerr<<label<<" valid="<<samples.size()<<" samples=";for(const auto sample:samples)std::cerr<<sample<<',';std::cerr<<" p50="<<(samples.empty()?0:P50(samples))<<" p95="<<(samples.empty()?0:P95(samples))<<" max="<<Maximum(samples)<<" timestampFrequency=not-exposed disjoint=not-applicable-d3d12 resolve="<<((timingAfter>timingBefore&&serialAfter>serialBefore)?"advanced":"stale")<<" timingSamples="<<timingBefore<<"->"<<timingAfter<<" serial="<<serialBefore<<"->"<<serialAfter<<'\n';}
